  "medios": [
    {
      "nombre": "El País",
      "titular_real": "Vox impone (PP–Vox en clave de “extremos y contagio”: negociación sustituida por “imposición”; afiliación/biografías tratadas como prueba de “ultra”; “independientes” entrecomillado; continuidad emocional con disturbios y titulares internacionales de polarización tecnológica/política)",
      "titular_traducido": "“No te preocupes por lo que acordaron: mira quién lo hace, súmate a la sospecha y entra al Senado por la puerta del pánico. ‘Independientes’, claro…”",
      "imd_local": 67,
      "palabra_cuchillo": "“independientes”",
      "tecnica_principal": "Framing moral por culpa por asociación (ultra-sospecha) + despolitización mediante sustitución semántica (negociación → imposición) y causalidad implícita (vínculos = amenaza)."
    },
    {
      "nombre": "El Mundo",
      "titular_real": "Control total del Senado (amenaza sistémica PP+Vox) mezclado con atmósfera de crimen y descontrol (escándalo Aldama/UCO/financiación PSOE; Black bloc/saqueos; “bandas latinoamericanas”); reducción de evaluación autónoma del acuerdo compitiendo con presión judicial y otros asuntos",
      "titular_traducido": "“Si el Senado cambia de manos, prepárate: viene ‘control total’ y, como bonus, el apocalipsis en la calle. Y mientras tanto, que no te dé tiempo a leer el acuerdo.”",
      "imd_local": 78,
      "palabra_cuchillo": "control total",
      "tecnica_principal": "Contaminación emocional por mezcla de encuadres (escándalo + amenaza sistémica + orden público/caos) para correlacionar afectos (peligro/violencia) con el acuerdo legislativo sin necesidad de evidencias del contenido."
    },
    {
      "nombre": "ABC",
      "titular_real": "No enmarca el Acuerdo PP–Vox: omisión explícita (agenda-setting por vacío), desplazando atención hacia consumo/entretenimiento y un caso celebrity",
      "titular_traducido": "“El acuerdo existe, sí… pero hoy no nos apetece. Si no lo nombras, no existe; y si no existe, que lo decida el feed.”",
      "imd_local": 38,
      "palabra_cuchillo": "—",
      "tecnica_principal": "Agenda-setting por omisión (sesgo por vacío): desplazamiento de atención mediante no-mención, evitando el marco informativo que permitiría evaluar el acuerdo."
    }
  ]
}
